WITH promo_sales AS (SELECT p.p_promo_id, p.p_promo_name, COUNT(DISTINCT ws.ws_order_number) AS total_orders, SUM(ws.ws_ext_sales_price) AS total_sales_revenue, SUM(ws.ws_ext_discount_amt) AS total_discount, AVG(ws.ws_ext_discount_amt) AS avg_discount_per_order, COUNT(DISTINCT c.c_customer_id) AS distinct_customers FROM web_sales ws INNER JOIN promotion p ON ws.ws_promo_sk = p.p_promo_sk INNER JOIN customer c ON ws.ws_bill_customer_sk = c.c_customer_sk GROUP BY p.p_promo_id, p.p_promo_name HAVING COUNT(DISTINCT ws.ws_order_number) >= 10) SELECT p.p_promo_id, p.p_promo_name, p.total_orders, p.total_sales_revenue, p.total_discount, p.avg_discount_per_order, CASE WHEN p.total_sales_revenue > 0 THEN (p.total_discount / p.total_sales_revenue) * 100 ELSE 0 END AS discount_rate_percent, p.distinct_customers, DENSE_RANK() OVER (ORDER BY p.total_sales_revenue DESC) AS sales_rev_rank, RANK() OVER (ORDER BY p.total_orders DESC) AS order_cnt_rank FROM promo_sales p ORDER BY p.total_sales_revenue DESC LIMIT 10
